#!/usr/bin/perl
# Cleans a collaboration graph generated by Doxygen (.dot file) for a class that uses generic classes:
# Doxygen draws a generic class twice, once as the template (e.g. "DT_Data< T >") and once as the
# instance (e.g. "DT_Data< Double >"), linked by an orange edge. This script merges each instance into
# its template, so that every class appears once.
#
# Usage:  perl merge_template_nodes.pl input.dot > output.dot
use strict;
use warnings;

local $/;                                   # read the whole file
my $dot = <>;
my ($head, $body) = $dot =~ /^(.*?\n)(  Node\d+ .*)$/s or die "Not a Doxygen graph\n";
my @statements = split /(?<=\];)\n/, $body; # every statement ends with "];"

# 1. orange edges: template -> instance
my %template_of;
for (@statements) {
    $template_of{$2} = $1 if /^\s*(Node\d+) -> (Node\d+) \[[^\n]*color="orange"/;
}

# 2. drop the orange edges and the instance nodes, redirect the other edges to the template
my @kept;
for (@statements) {
    next if /^\s*Node\d+ -> Node\d+ \[[^\n]*color="orange"/;
    next if /^\s*(Node\d+) \[/ && exists $template_of{$1};
    s/\b(Node\d+)\b(?= ->| \[id="edge)/exists $template_of{$1} ? $template_of{$1} : $1/ge;
    push @kept, $_;
}
print $head, join("\n", @kept);
